#include <stdio.h>
#include <string.h>
#include "bzlib.h"
int consumer_roundtrip(void) {
  char src[] = "header consumer roundtrip payload";
  char packed[512], plain[64];
  unsigned int packed_len = sizeof packed, plain_len = sizeof plain;
  if (BZ2_bzBuffToBuffCompress(packed, &packed_len, src, (unsigned int)sizeof src, 9, 0, 30) != BZ_OK) return 0;
  if (BZ2_bzBuffToBuffDecompress(plain, &plain_len, packed, packed_len, 0, 0) != BZ_OK) return 0;
  return plain_len == sizeof src && memcmp(plain, src, sizeof src) == 0;
}

#include <stdio.h>
#include <string.h>
#include "bzlib.h"
int consumer_roundtrip(void);
int main(void) {
  bz_stream s;
  memset(&s, 0, sizeof s);
  if (BZ2_bzCompressInit(&s, 10, 0, 0) != BZ_PARAM_ERROR) return 1;
  if (BZ2_bzCompressInit(&s, 1, 0, 0) != BZ_OK) return 1;
  if (BZ2_bzCompressEnd(&s) != BZ_OK) return 1;
  return consumer_roundtrip() && strncmp(BZ2_bzlibVersion(), "1.0.8", 5) == 0 ? 0 : 1;
}

#include <cstdio>
#include <cstring>
#include "bzlib.h"
bool consumer_cpp_roundtrip() {
  char src[] = "C++ header consumer roundtrip payload";
  char packed[512], plain[64];
  unsigned int packed_len = sizeof packed, plain_len = sizeof plain;
  if (BZ2_bzBuffToBuffCompress(packed, &packed_len, src, (unsigned int)sizeof src, 9, 0, 30) != BZ_OK) return false;
  if (BZ2_bzBuffToBuffDecompress(plain, &plain_len, packed, packed_len, 0, 0) != BZ_OK) return false;
  return plain_len == sizeof src && std::memcmp(plain, src, sizeof src) == 0;
}

#include <cstdio>
#include <cstring>
#include "bzlib.h"
bool consumer_cpp_roundtrip();
int main() {
  bz_stream s = {};
  if (BZ2_bzCompressInit(&s, 10, 0, 0) != BZ_PARAM_ERROR) return 1;
